<section class="heading"><span class="eyebrow">Учебная коллекция</span><h1>Каталог товаров</h1><p class="muted">Книги, курсы и инструменты для учёбы.</p></section>
<section class="panel"><form class="filter-grid" method="get" action="/catalog"><div><label for="category">Категория</label><select name="category" id="category"><option value="">Все категории</option><?php foreach ($categories as $item): ?><option value="<?= $item->id ?>" <?= $category === $item->id ? 'selected' : '' ?>><?= e($item->name) ?></option><?php endforeach ?></select></div><div><label for="sort">Сортировка</label><select name="sort" id="sort"><?php foreach (['name' => 'По названию', 'price' => 'Сначала дешевле', 'price_desc' => 'Сначала дороже'] as $key => $label): ?><option value="<?= e($key) ?>" <?= $sort === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach ?></select></div><button>Применить</button></form><p class="muted">Найдено товаров: <?= count($products) ?> · <a href="/catalog">Сбросить фильтры</a></p></section>
<?php if (!$products): ?><p class="empty">В выбранной категории нет товаров.</p><?php endif ?>
<section class="cards" aria-label="Товары"><?php foreach ($products as $product): ?><article class="panel product" data-id="<?= $product->id ?>"><span class="badge"><?= e($product->category->name) ?></span><h2><a href="/product/<?= $product->id ?>"><?= e($product->name) ?></a></h2><p class="price"><?= money($product->priceCents) ?></p><p class="muted stock"><?= $product->stock > 0 ? 'В наличии: ' . $product->stock . ' шт.' : 'Нет в наличии' ?></p><div class="actions"><a href="/product/<?= $product->id ?>">Подробнее →</a></div></article><?php endforeach ?></section>
